ruleExplanation:
'1) Неверно: «Как художник создаёт пейзажную картину» — это не сравнительный оборот, а полноценное придаточное сравнительное предложение со своей основой («художник создаёт»). 2) Неверно: «старой, дореволюционной» — однородные необособленные определения перед определяемым словом («например» — вводное слово). 3) Верно: однородные члены «в ландшафт и пейзаж», а также «с парками, системами». 4) Верно: простое неполное предложение с одной основой («деревеньки и сёла»). 5) Верно: СПП с придаточным времени, присоединяемым союзом «когда».',
hint: 'Если после «как» есть своя грамматическая основа («художник создаёт»), это придаточное сравнительное, а не сравнительный оборот.',
