          '(1)Когда-то в странах Востока для украшения жилищ держали карасей в вазах с водой. (2)Любители рыб заметили, что не все караси одинаковые по окраске: среди них попадаются рыбки и с золотистой чешуёй, и с бронзовой, и с красноватой, и с серебристой. (3)С помощью долгого и терпеливого отбора, путём многократного скрещивания люди вывели множество рыб, необычных не только по цвету, но и по форме. (4)Так появились вуалехвост, телескоп, комета, львиноголовка и многие другие обитатели аквариумов. (5)А родоначальник этих причудливых рыб – неприхотливый карась.',
